use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Generate arbitrary structured values from raw, unstructured data."] # [doc = ""] # [doc = " The `Arbitrary` trait allows you to generate valid structured values, like"] # [doc = " `HashMap`s, or ASTs, or `MyTomlConfig`, or any other data structure from"] # [doc = " raw, unstructured bytes provided by a fuzzer."] # [doc = ""] # [doc = " # Deriving `Arbitrary`"] # [doc = ""] # [doc = " Automatically deriving the `Arbitrary` trait is the recommended way to"] # [doc = " implement `Arbitrary` for your types."] # [doc = ""] # [doc = " Using the custom derive requires that you enable the `\"derive\"` cargo"] # [doc = " feature in your `Cargo.toml`:"] # [doc = ""] # [doc = " ```toml"] # [doc = " [dependencies]"] # [doc = " arbitrary = { version = \"1\", features = [\"derive\"] }"] # [doc = " ```"] # [doc = ""] # [doc = " Then, you add the `#[derive(Arbitrary)]` annotation to your `struct` or"] # [doc = " `enum` type definition:"] # [doc = ""] # [doc = " ```"] # [doc = " # #[cfg(feature = \"derive\")] mod foo {"] # [doc = " use arbitrary::Arbitrary;"] # [doc = " use std::collections::HashSet;"] # [doc = ""] # [doc = " #[derive(Arbitrary)]"] # [doc = " pub struct AddressBook {"] # [doc = "     friends: HashSet<Friend>,"] # [doc = " }"] # [doc = ""] # [doc = " #[derive(Arbitrary, Hash, Eq, PartialEq)]"] # [doc = " pub enum Friend {"] # [doc = "     Buddy { name: String },"] # [doc = "     Pal { age: usize },"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " Every member of the `struct` or `enum` must also implement `Arbitrary`."] # [doc = ""] # [doc = " It is also possible to change the default bounds added by the derive:"] # [doc = ""] # [doc = " ```"] # [doc = " # #[cfg(feature = \"derive\")] mod foo {"] # [doc = " use arbitrary::Arbitrary;"] # [doc = ""] # [doc = " trait Trait {"] # [doc = "     type Assoc: for<'a> Arbitrary<'a>;"] # [doc = " }"] # [doc = ""] # [doc = " #[derive(Arbitrary)]"] # [doc = " // The bounds are used verbatim, so any existing trait bounds will need to be repeated."] # [doc = " #[arbitrary(bound = \"T: Trait\")]"] # [doc = " struct Point<T: Trait> {"] # [doc = "     x: T::Assoc,"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " # Implementing `Arbitrary` By Hand"] # [doc = ""] # [doc = " Implementing `Arbitrary` mostly involves nested calls to other `Arbitrary`"] # [doc = " arbitrary implementations for each of your `struct` or `enum`'s members. But"] # [doc = " sometimes you need some amount of raw data, or you need to generate a"] # [doc = " variably-sized collection type, or something of that sort. The"] # [doc = " [`Unstructured`] type helps you with these tasks."] # [doc = ""] # [doc = " ```"] # [doc = " # #[cfg(feature = \"derive\")] mod foo {"] # [doc = " # pub struct MyCollection<T> { _t: std::marker::PhantomData<T> }"] # [doc = " # impl<T> MyCollection<T> {"] # [doc = " #     pub fn new() -> Self { MyCollection { _t: std::marker::PhantomData } }"] # [doc = " #     pub fn insert(&mut self, element: T) {}"] # [doc = " # }"] # [doc = " use arbitrary::{Arbitrary, Result, Unstructured};"] # [doc = ""] # [doc = " impl<'a, T> Arbitrary<'a> for MyCollection<T>"] # [doc = " where"] # [doc = "     T: Arbitrary<'a>,"] # [doc = " {"] # [doc = "     fn arbitrary(u: &mut Unstructured<'a>) -> Result<Self> {"] # [doc = "         // Get an iterator of arbitrary `T`s."] # [doc = "         let iter = u.arbitrary_iter::<T>()?;"] # [doc = ""] # [doc = "         // And then create a collection!"] # [doc = "         let mut my_collection = MyCollection::new();"] # [doc = "         for elem_result in iter {"] # [doc = "             let elem = elem_result?;"] # [doc = "             my_collection.insert(elem);"] # [doc = "         }"] # [doc = ""] # [doc = "         Ok(my_collection)"] # [doc = "     }"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " # A Note On Output Distributions"] # [doc = ""] # [doc = " There is no requirement for a particular distribution of the values. For"] # [doc = " example, it is not required that every value appears with the same"] # [doc = " probability. That being said, the main use for `Arbitrary` is for fuzzing,"] # [doc = " so in many cases a uniform distribution will make the most sense in order to"] # [doc = " provide the best coverage of the domain. In other cases this is not"] # [doc = " desirable or even possible, for example when sampling from a uniform"] # [doc = " distribution is computationally expensive or in the case of collections that"] # [doc = " may grow indefinitely."] pub trait Arbitrary < 'a > : Sized { # [doc = " Generate an arbitrary value of `Self` from the given unstructured data."] # [doc = ""] # [doc = " Calling `Arbitrary::arbitrary` requires that you have some raw data,"] # [doc = " perhaps given to you by a fuzzer like AFL or libFuzzer. You wrap this"] # [doc = " raw data in an `Unstructured`, and then you can call `<MyType as"] # [doc = " Arbitrary>::arbitrary` to construct an arbitrary instance of `MyType`"] # [doc = " from that unstructured data."] # [doc = ""] # [doc = " Implementations may return an error if there is not enough data to"] # [doc = " construct a full instance of `Self`, or they may fill out the rest of"] # [doc = " `Self` with dummy values. Using dummy values when the underlying data is"] # [doc = " exhausted can help avoid accidentally \"defeating\" some of the fuzzer's"] # [doc = " mutations to the underlying byte stream that might otherwise lead to"] # [doc = " interesting runtime behavior or new code coverage if only we had just a"] # [doc = " few more bytes. However, it also requires that implementations for"] # [doc = " recursive types (e.g. `struct Foo(Option<Box<Foo>>)`) avoid infinite"] # [doc = " recursion when the underlying data is exhausted."] # [doc = ""] # [doc = " ```"] # [doc = " # #[cfg(feature = \"derive\")] fn foo() {"] # [doc = " use arbitrary::{Arbitrary, Unstructured};"] # [doc = ""] # [doc = " #[derive(Arbitrary)]"] # [doc = " pub struct MyType {"] # [doc = "     // ..."] # [doc = " }"] # [doc = ""] # [doc = " // Get the raw data from the fuzzer or wherever else."] # [doc = " # let get_raw_data_from_fuzzer = || &[];"] # [doc = " let raw_data: &[u8] = get_raw_data_from_fuzzer();"] # [doc = ""] # [doc = " // Wrap that raw data in an `Unstructured`."] # [doc = " let mut unstructured = Unstructured::new(raw_data);"] # [doc = ""] # [doc = " // Generate an arbitrary instance of `MyType` and do stuff with it."] # [doc = " if let Ok(value) = MyType::arbitrary(&mut unstructured) {"] # [doc = " #   let do_stuff = |_| {};"] # [doc = "     do_stuff(value);"] # [doc = " }"] # [doc = " # }"] # [doc = " ```"] # [doc = ""] # [doc = " See also the documentation for [`Unstructured`]."] fn arbitrary (u : & mut Unstructured < 'a >) -> Result < Self > ; # [doc = " Generate an arbitrary value of `Self` from the entirety of the given"] # [doc = " unstructured data."] # [doc = ""] # [doc = " This is similar to Arbitrary::arbitrary, however it assumes that it is"] # [doc = " the last consumer of the given data, and is thus able to consume it all"] # [doc = " if it needs.  See also the documentation for"] # [doc = " [`Unstructured`]."] fn arbitrary_take_rest (mut u : Unstructured < 'a >) -> Result < Self > { Self :: arbitrary (& mut u) } # [doc = " Get a size hint for how many bytes out of an `Unstructured` this type"] # [doc = " needs to construct itself."] # [doc = ""] # [doc = " This is useful for determining how many elements we should insert when"] # [doc = " creating an arbitrary collection."] # [doc = ""] # [doc = " The return value is similar to [`Iterator::size_hint`]: it returns a"] # [doc = " tuple where the first element is a lower bound on the number of bytes"] # [doc = " required, and the second element is an optional upper bound."] # [doc = ""] # [doc = " The default implementation return `(0, None)` which is correct for any"] # [doc = " type, but not ultimately that useful. Using `#[derive(Arbitrary)]` will"] # [doc = " create a better implementation. If you are writing an `Arbitrary`"] # [doc = " implementation by hand, and your type can be part of a dynamically sized"] # [doc = " collection (such as `Vec`), you are strongly encouraged to override this"] # [doc = " default with a better implementation, and also override"] # [doc = " [`try_size_hint`]."] # [doc = ""] # [doc = " ## How to implement this"] # [doc = ""] # [doc = " If the size hint calculation is a trivial constant and does not recurse"] # [doc = " into any other `size_hint` call, you should implement it in `size_hint`:"] # [doc = ""] # [doc = " ```"] # [doc = " use arbitrary::{size_hint, Arbitrary, Result, Unstructured};"] # [doc = ""] # [doc = " struct SomeStruct(u8);"] # [doc = ""] # [doc = " impl<'a> Arbitrary<'a> for SomeStruct {"] # [doc = "     fn arbitrary(u: &mut Unstructured<'a>) -> Result<Self> {"] # [doc = "         let buf = &mut [0];"] # [doc = "         u.fill_buffer(buf)?;"] # [doc = "         Ok(SomeStruct(buf[0]))"] # [doc = "     }"] # [doc = ""] # [doc = "     #[inline]"] # [doc = "     fn size_hint(depth: usize) -> (usize, Option<usize>) {"] # [doc = "         let _ = depth;"] # [doc = "         (1, Some(1))"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " Otherwise, it should instead be implemented in [`try_size_hint`],"] # [doc = " and the `size_hint` implementation should forward to it:"] # [doc = ""] # [doc = " ```"] # [doc = " use arbitrary::{size_hint, Arbitrary, MaxRecursionReached, Result, Unstructured};"] # [doc = ""] # [doc = " struct SomeStruct<A, B> {"] # [doc = "     a: A,"] # [doc = "     b: B,"] # [doc = " }"] # [doc = ""] # [doc = " impl<'a, A: Arbitrary<'a>, B: Arbitrary<'a>> Arbitrary<'a> for SomeStruct<A, B> {"] # [doc = "     fn arbitrary(u: &mut Unstructured<'a>) -> Result<Self> {"] # [doc = "         // ..."] # [doc = " #       todo!()"] # [doc = "     }"] # [doc = ""] # [doc = "     fn size_hint(depth: usize) -> (usize, Option<usize>) {"] # [doc = "         // Return the value of try_size_hint"] # [doc = "         //"] # [doc = "         // If the recursion fails, return the default, always valid `(0, None)`"] # [doc = "         Self::try_size_hint(depth).unwrap_or_default()"] # [doc = "     }"] # [doc = ""] # [doc = "     fn try_size_hint(depth: usize) -> Result<(usize, Option<usize>), MaxRecursionReached> {"] # [doc = "         // Protect against potential infinite recursion with"] # [doc = "         // `try_recursion_guard`."] # [doc = "         size_hint::try_recursion_guard(depth, |depth| {"] # [doc = "             // If we aren't too deep, then `recursion_guard` calls"] # [doc = "             // this closure, which implements the natural size hint."] # [doc = "             // Don't forget to use the new `depth` in all nested"] # [doc = "             // `try_size_hint` calls! We recommend shadowing the"] # [doc = "             // parameter, like what is done here, so that you can't"] # [doc = "             // accidentally use the wrong depth."] # [doc = "             Ok(size_hint::and("] # [doc = "                 <A as Arbitrary>::try_size_hint(depth)?,"] # [doc = "                 <B as Arbitrary>::try_size_hint(depth)?,"] # [doc = "             ))"] # [doc = "         })"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " ## Invariant"] # [doc = ""] # [doc = " It must be possible to construct every possible output using only inputs"] # [doc = " of lengths bounded by these parameters. This applies to both"] # [doc = " [`Arbitrary::arbitrary`] and [`Arbitrary::arbitrary_take_rest`]."] # [doc = ""] # [doc = " This is trivially true for `(0, None)`. To restrict this further, it"] # [doc = " must be proven that all inputs that are now excluded produced redundant"] # [doc = " outputs which are still possible to produce using the reduced input"] # [doc = " space."] # [doc = ""] # [doc = " [iterator-size-hint]: https://doc.rust-lang.org/stable/std/iter/trait.Iterator.html#method.size_hint"] # [doc = " [`try_size_hint`]: Arbitrary::try_size_hint"] # [inline] fn size_hint (depth : usize) -> (usize , Option < usize >) { let _ = depth ; (0 , None) } # [doc = " Get a size hint for how many bytes out of an `Unstructured` this type"] # [doc = " needs to construct itself."] # [doc = ""] # [doc = " Unlike [`size_hint`], this function keeps the information that the"] # [doc = " recursion limit was reached. This is required to \"short circuit\" the"] # [doc = " calculation and avoid exponential blowup with recursive structures."] # [doc = ""] # [doc = " If you are implementing [`size_hint`] for a struct that could be"] # [doc = " recursive, you should implement `try_size_hint` and call the"] # [doc = " `try_size_hint` when recursing"] # [doc = ""] # [doc = ""] # [doc = " The return value is similar to [`core::iter::Iterator::size_hint`]: it"] # [doc = " returns a tuple where the first element is a lower bound on the number"] # [doc = " of bytes required, and the second element is an optional upper bound."] # [doc = ""] # [doc = " The default implementation returns the value of [`size_hint`] which is"] # [doc = " correct for any type, but might lead to exponential blowup when dealing"] # [doc = " with recursive types."] # [doc = ""] # [doc = " ## Invariant"] # [doc = ""] # [doc = " It must be possible to construct every possible output using only inputs"] # [doc = " of lengths bounded by these parameters. This applies to both"] # [doc = " [`Arbitrary::arbitrary`] and [`Arbitrary::arbitrary_take_rest`]."] # [doc = ""] # [doc = " This is trivially true for `(0, None)`. To restrict this further, it"] # [doc = " must be proven that all inputs that are now excluded produced redundant"] # [doc = " outputs which are still possible to produce using the reduced input"] # [doc = " space."] # [doc = ""] # [doc = " ## When to implement `try_size_hint`"] # [doc = ""] # [doc = " If you 100% know that the type you are implementing `Arbitrary` for is"] # [doc = " not a recursive type, or your implementation is not transitively calling"] # [doc = " any other `size_hint` methods, you may implement [`size_hint`], and the"] # [doc = " default `try_size_hint` implementation will use it."] # [doc = ""] # [doc = " Note that if you are implementing `Arbitrary` for a generic type, you"] # [doc = " cannot guarantee the lack of type recursion!"] # [doc = ""] # [doc = " Otherwise, when there is possible type recursion, you should implement"] # [doc = " `try_size_hint` instead."] # [doc = ""] # [doc = " ## The `depth` parameter"] # [doc = ""] # [doc = " When implementing `try_size_hint`, you need to use"] # [doc = " [`arbitrary::size_hint::try_recursion_guard(depth)`][crate::size_hint::try_recursion_guard]"] # [doc = " to prevent potential infinite recursion when calculating size hints for"] # [doc = " potentially recursive types:"] # [doc = ""] # [doc = " ```"] # [doc = " use arbitrary::{size_hint, Arbitrary, MaxRecursionReached, Unstructured};"] # [doc = ""] # [doc = " // This can potentially be a recursive type if `L` or `R` contain"] # [doc = " // something like `Box<Option<MyEither<L, R>>>`!"] # [doc = " enum MyEither<L, R> {"] # [doc = "     Left(L),"] # [doc = "     Right(R),"] # [doc = " }"] # [doc = ""] # [doc = " impl<'a, L, R> Arbitrary<'a> for MyEither<L, R>"] # [doc = " where"] # [doc = "     L: Arbitrary<'a>,"] # [doc = "     R: Arbitrary<'a>,"] # [doc = " {"] # [doc = "     fn arbitrary(u: &mut Unstructured) -> arbitrary::Result<Self> {"] # [doc = "         // ..."] # [doc = " #       unimplemented!()"] # [doc = "     }"] # [doc = ""] # [doc = "     fn size_hint(depth: usize) -> (usize, Option<usize>) {"] # [doc = "         // Return the value of `try_size_hint`"] # [doc = "         //"] # [doc = "         // If the recursion fails, return the default `(0, None)` range,"] # [doc = "         // which is always valid."] # [doc = "         Self::try_size_hint(depth).unwrap_or_default()"] # [doc = "     }"] # [doc = ""] # [doc = "     fn try_size_hint(depth: usize) -> Result<(usize, Option<usize>), MaxRecursionReached> {"] # [doc = "         // Protect against potential infinite recursion with"] # [doc = "         // `try_recursion_guard`."] # [doc = "         size_hint::try_recursion_guard(depth, |depth| {"] # [doc = "             // If we aren't too deep, then `recursion_guard` calls"] # [doc = "             // this closure, which implements the natural size hint."] # [doc = "             // Don't forget to use the new `depth` in all nested"] # [doc = "             // `try_size_hint` calls! We recommend shadowing the"] # [doc = "             // parameter, like what is done here, so that you can't"] # [doc = "             // accidentally use the wrong depth."] # [doc = "             Ok(size_hint::or("] # [doc = "                 <L as Arbitrary>::try_size_hint(depth)?,"] # [doc = "                 <R as Arbitrary>::try_size_hint(depth)?,"] # [doc = "             ))"] # [doc = "         })"] # [doc = "     }"] # [doc = " }"] # [doc = " ```"] # [inline] fn try_size_hint (depth : usize) -> Result < (usize , Option < usize >) , MaxRecursionReached > { Ok (Self :: size_hint (depth)) } }